let original := snapshot()
mut i := 0
while i < 16 { 
mut caught := false
try { fail() } except e { caught = true }
assert(caught)

i += 1 }
assert_equal(original.row[0], 0)
let current := snapshot()
assert_equal(current.row[0], 16)
print("NEGATIVE OPERAND PASS")

