from owner import snapshot, fail
let original := snapshot()
mut i := 0
while i < 16 { let saved := snapshot()
mut caught := false
try { fail() } except e { caught = true }
assert(caught)
assert_equal(saved.row[0], i)
i += 1 }
assert_equal(original.row[0], 0)
